    @m2m_interface_availability_check
    def get_vdu_cell_id(self, timeout):
        cell_list = self.status_api.get_vdu_cells_diff(_request_timeout=timeout)

        cells_statuses = []
        required_keys = ['name', 'nr_cell_identity']
        created_cells = cell_list.created

        if len(created_cells) > 0:
            for cell in created_cells:
                statuses = {
                    getattr(cell.basic_cell, 'name'): (getattr(cell.basic_cell, 'nr_cell_identity')
                                                       if hasattr(cell.basic_cell, key) else getattr(cell, key))
                    for key in required_keys
                }
                cells_statuses.append(statuses)

        return cells_statuses

