    def perform_commissioning(self, scf_file, wait_for_completion=True, should_activate=True, timeout=300):
        operation = self.local_client.perform_commissioning(scf_file=scf_file, should_activate=should_activate,
                                                            timeout=30)
        if wait_for_completion:
            method_name = "get_status_of_perform_commissioning" if should_activate \
                else "get_status_of_perform_commissioning_without_activation"

            return poll_status(instance=self.local_client, method_name=method_name,
                               operation_id=operation["id"], timeout=timeout)
        return operation

