        if should_activate:
            return self.local_client.get_status_of_perform_commissioning(operation_id=operation_id, timeout=timeout)

        else:
            return self.local_client.get_status_of_perform_commissioning_without_activation(operation_id=operation_id,
                                                                                            timeout=timeout)

