    @m2m_interface_availability_check
    def get_screl_history_file(self, directory, timeout=30):
        file_id = 'screl_history_' + time.strftime('%Y%m%d%H%M%S', time.gmtime())
        file_path = os.path.join(directory, file_id)
        file_content = self.local_client.get_screl_history_file(timeout=timeout)
        with open(file_path, 'wb') as f:
            f.write(file_content)
        return file_path

    @m2m_interface_availability_check
    def collect_screl(self, directory, coverage, screl_type, compressed, timeout=600):
        trigger_response = self.local_client.trigger_screl_collection(coverage=coverage, screl_type=screl_type)
        operation_id = trigger_response['operationId']
        files_list = self._wait_for_screl_collection_to_finish(operation_id=operation_id,
                                                               timeout=timeout)
        download_path = self.download_screl_files(operation_id=operation_id,
                                                  files_list=files_list,
                                                  directory=directory,
                                                  compressed=compressed)
        self.local_client.delete_screl_collection_operation(operation_id=operation_id)
        return download_path

    def _wait_for_screl_collection_to_finish(self, operation_id, timeout=600):
        operation_info = poll_status(instance=self.local_client, method_name="get_screl_operation_info",
                                     operation_id=operation_id, timeout=timeout,
                                     teardown_method_name="delete_screl_collection_operation")
        return operation_info['files']

    @m2m_interface_availability_check
    def download_screl_files(self, operation_id, files_list, directory, compressed, timeout=30):
        archive_name = 'SCREL_' + time.strftime('%Y%m%d%H%M%S', time.gmtime()) + '.zip'
        archive_path = os.path.join(directory, archive_name)

        for file_obj in files_list:
            file_id = file_obj['fileId']
            file_path = os.path.join(directory, file_id)
            file_content = self.local_client.download_screl_file(operation_id=operation_id,
                                                                 file_id=file_id,
                                                                 timeout=timeout)
            with open(file_path, 'wb') as f:
                f.write(file_content)

            if compressed:
                with zipfile.ZipFile(archive_path, 'a', zipfile.ZIP_DEFLATED) as archive:
                    archive.write(filename=file_path, arcname=file_id)
                os.remove(file_path)

        if compressed:
            return archive_path
        else:
            return directory

