    def get_local_snapshot(self, directory, request_timeout=30, operation_timeout=600.0, compressed=False,
                           coverage='full', filter_regx=None):
        operation_id = self.local_client.trigger_snapshot(coverage=coverage,
                                                          originator='M2M',
                                                          snapshot_type='local',
                                                          filter_regx=filter_regx)['operationId']

        start_time = time.time()
        snapshot_path = save_snapshot(instance=self,
                                      start_time=start_time,
                                      operation_id=operation_id,
                                      operation_timeout=operation_timeout,
                                      directory=directory,
                                      compressed=compressed,
                                      request_timeout=request_timeout)
        teardown_for_snapshot_collection(instance=self,
                                         start_time=start_time,
                                         operation_id=operation_id,
                                         request_timeout=request_timeout,
                                         operation_timeout=operation_timeout)

        return snapshot_path

    @m2m_interface_availability_check
    def trigger_local_snapshot(self, request_timeout=30, coverage='full', filter_regx=None):
        response = self.local_client.trigger_snapshot(coverage=coverage, originator='M2M', snapshot_type='local',
                                                      filter_regx=filter_regx, timeout=request_timeout)
        return response['operationId']
